UPDATE email_templates SET html_body='<div style="font-family: -apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, sans-serif; background: #F8FAFC; padding: 32px 16px;"><div style="max-width: 640px; margin: 0 auto;"><div style="background: white; border-radius: 16px; padding: 36px; box-shadow: 0 2px 12px rgba(15,23,42,0.06);"><h1 style="font-size: 24px; color: #0F172A; margin: 0 0 12px; font-weight: 700;">Добрый день, {{name}}!</h1> <p style="font-size: 15px; color: #475569; line-height: 1.7; margin: 0 0 16px;">Меня зовут <strong style="color:#0F172A">команда Sintagma</strong> — мы делаем образовательную платформу полного цикла для учебных центров и предприятий.</p> <p style="font-size: 15px; color: #475569; line-height: 1.7; margin: 0 0 16px;">Коротко, что умеет платформа:</p> <ul style="font-size: 14px; color: #475569; line-height: 1.8; padding-left: 20px; margin: 0 0 16px;"><li>200+ готовых программ ДПО, ПО и «Рабочих профессий» — можно сразу обучать</li><li>ИИ-конструктор: курс из 35 уроков создаётся за 5 минут</li><li>Авто-выпуск удостоверений и отчётность ФИС ФРДО без Excel вручную</li><li>Видеохостинг с защитой от скачивания + вебинары</li></ul> <p style="font-size: 15px; color: #475569; line-height: 1.7; margin: 0 0 8px;">Удобно ли вам короткий 20-минутный созвон, чтобы я показал платформу на вашей задаче?</p> <div style="text-align: center; margin: 28px 0 8px;"><a href="{{action_url}}" style="display: inline-block; background: #1AAB9B; color: white; padding: 14px 36px; border-radius: 12px; text-decoration: none; font-weight: 600; font-size: 15px; box-shadow: 0 4px 12px rgba(26,171,155,0.25);">Запланировать встречу</a></div></div> <p style="font-size: 11px; color: #94A3B8; margin: 20px 0 0; text-align: center; line-height: 1.5;"> Платформа Sintagma — <a href="https://sintagma.com.ru" style="color: #94A3B8; text-decoration: underline;">sintagma.com.ru</a><br/> Если вы не хотите получать письма от Sintagma — ответьте на это письмо словом «СТОП». </p> </div></div>', subject='Sintagma — образовательная платформа для УЦ и предприятий', category='cold', updated_at=now() WHERE scope='platform' AND name='Знакомство — холодное';

UPDATE email_templates SET html_body='<div style="font-family: -apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, sans-serif; background: #F8FAFC; padding: 32px 16px;"><div style="max-width: 640px; margin: 0 auto;"><div style="background: white; border-radius: 16px; padding: 36px; box-shadow: 0 2px 12px rgba(15,23,42,0.06);"><div style="text-align: center; margin: 0 0 24px;"><div style="display: inline-block; background: linear-gradient(135deg, #1AAB9B, #138577); color: white; font-size: 12px; font-weight: 700; letter-spacing: 1px; padding: 6px 14px; border-radius: 999px; text-transform: uppercase;">Презентация платформы</div></div> <h1 style="font-size: 26px; color: #0F172A; margin: 0 0 12px; font-weight: 700; text-align: center; line-height: 1.25;">Sintagma — образовательная платформа полного цикла</h1> <p style="font-size: 15px; color: #475569; line-height: 1.7; margin: 0 0 24px; text-align: center;">Для учебных центров, корпоративных университетов и охраны труда. Подготовили подборку специально для <strong style="color:#0F172A">{{name}}</strong>.</p> <h2 style="font-size: 16px; font-weight: 700; color: #0F172A; margin: 28px 0 8px; padding-top: 8px; border-top: 1px solid #E2E8F0;">🚀 Что даёт платформа</h2> <table cellpadding="0" cellspacing="0" border="0" style="width: 100%; margin: 0 0 8px;"> <tr><td style="padding: 14px 0; vertical-align: top; width: 48px;"><div style="width: 40px; height: 40px; background: #1AAB9B15; border-radius: 10px; text-align: center; line-height: 40px; font-size: 20px;">🎓</div></td><td style="padding: 14px 0 14px 14px; vertical-align: top;"><div style="font-size: 15px; font-weight: 600; color: #0F172A; margin: 0 0 4px;">200+ готовых программ</div><div style="font-size: 14px; color: #475569; line-height: 1.55;">Маркетплейс ДПО, ПО и «Рабочих профессий» — обучайте сразу, без разработки с нуля.</div></td></tr> <tr><td style="padding: 14px 0; vertical-align: top; width: 48px;"><div style="width: 40px; height: 40px; background: #1AAB9B15; border-radius: 10px; text-align: center; line-height: 40px; font-size: 20px;">🤖</div></td><td style="padding: 14px 0 14px 14px; vertical-align: top;"><div style="font-size: 15px; font-weight: 600; color: #0F172A; margin: 0 0 4px;">ИИ-конструктор курсов</div><div style="font-size: 14px; color: #475569; line-height: 1.55;">GigaChat + Gemini: курс из 35 уроков по 700+ слов и тестами за 5 минут.</div></td></tr> <tr><td style="padding: 14px 0; vertical-align: top; width: 48px;"><div style="width: 40px; height: 40px; background: #1AAB9B15; border-radius: 10px; text-align: center; line-height: 40px; font-size: 20px;">📊</div></td><td style="padding: 14px 0 14px 14px; vertical-align: top;"><div style="font-size: 15px; font-weight: 600; color: #0F172A; margin: 0 0 4px;">ФИС ФРДО автоматически</div><div style="font-size: 14px; color: #475569; line-height: 1.55;">Excel 35/41 колонка, форматирование СНИЛС и дат — без ручной работы.</div></td></tr> <tr><td style="padding: 14px 0; vertical-align: top; width: 48px;"><div style="width: 40px; height: 40px; background: #1AAB9B15; border-radius: 10px; text-align: center; line-height: 40px; font-size: 20px;">🎬</div></td><td style="padding: 14px 0 14px 14px; vertical-align: top;"><div style="font-size: 15px; font-weight: 600; color: #0F172A; margin: 0 0 4px;">Видео и вебинары</div><div style="font-size: 14px; color: #475569; line-height: 1.55;">Видеохостинг Kinescope с DRM и защитой от скачивания + LiveKit для вебинаров.</div></td></tr> </table> <h2 style="font-size: 16px; font-weight: 700; color: #0F172A; margin: 28px 0 8px; padding-top: 8px; border-top: 1px solid #E2E8F0;">📑 Документооборот под ключ</h2> <ul style="font-size: 14px; color: #475569; line-height: 1.8; padding-left: 20px; margin: 8px 0 0;"><li>Авто-выпуск удостоверений и дипломов при 100% прогресса ученика</li><li>Электронная подпись (63-ФЗ), журналы регистрации, корзина с восстановлением</li><li>Договоры, КП, счета, акты сверки — генерация в Word/PDF из реквизитов</li><li>Массовая генерация документов по шаблонам с переменными</li></ul> <h2 style="font-size: 16px; font-weight: 700; color: #0F172A; margin: 28px 0 8px; padding-top: 8px; border-top: 1px solid #E2E8F0;">🛡 Безопасность и соответствие</h2> <ul style="font-size: 14px; color: #475569; line-height: 1.8; padding-left: 20px; margin: 8px 0 0;"><li>Шифрование персональных данных (паспорта, СНИЛС) на уровне БД</li><li>Соответствие 54-ФЗ, 63-ФЗ, 152-ФЗ</li><li>Серверная проверка тестов — ученик не увидит правильные ответы</li><li>Гранулярные права для сотрудников + 2FA для администраторов</li></ul> <h2 style="font-size: 16px; font-weight: 700; color: #0F172A; margin: 28px 0 8px; padding-top: 8px; border-top: 1px solid #E2E8F0;">💰 Гибкость тарифов</h2> <p style="font-size: 14px; color: #475569; line-height: 1.7; margin: 8px 0 0;"><strong style="color:#0F172A">Free Forever</strong> — до 10 учеников бесплатно, без срока. Ещё 4 тарифа — от Старта до Максимального. Кастомные лимиты — по запросу.</p> <div style="text-align: center; margin: 28px 0 8px;"><a href="{{action_url}}" style="display: inline-block; background: #1AAB9B; color: white; padding: 14px 36px; border-radius: 12px; text-decoration: none; font-weight: 600; font-size: 15px; box-shadow: 0 4px 12px rgba(26,171,155,0.25);">Перейти к встрече</a></div> <p style="font-size: 13px; color: #94A3B8; line-height: 1.6; margin: 16px 0 0; text-align: center;">Если ссылка не открывается — ответьте на это письмо, мы пришлём новое приглашение.</p></div> <p style="font-size: 11px; color: #94A3B8; margin: 20px 0 0; text-align: center; line-height: 1.5;"> Платформа Sintagma — <a href="https://sintagma.com.ru" style="color: #94A3B8; text-decoration: underline;">sintagma.com.ru</a><br/> Если вы не хотите получать письма от Sintagma — ответьте на это письмо словом «СТОП». </p> </div></div>', subject='Презентация платформы Sintagma — что внутри', category='presentation', updated_at=now() WHERE scope='platform' AND name='Приглашение на презентацию';

UPDATE email_templates SET html_body='<div style="font-family: -apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, sans-serif; background: #F8FAFC; padding: 32px 16px;"><div style="max-width: 640px; margin: 0 auto;"><div style="background: white; border-radius: 16px; padding: 36px; box-shadow: 0 2px 12px rgba(15,23,42,0.06);"><h1 style="font-size: 22px; color: #0F172A; margin: 0 0 16px; font-weight: 700;">Спасибо за встречу!</h1> <p style="font-size: 15px; color: #475569; line-height: 1.7; margin: 0 0 16px;">Было приятно познакомиться с командой {{name}}. Как и договаривались, отправляю материалы:</p> <ul style="font-size: 14px; color: #475569; line-height: 1.8; padding-left: 20px; margin: 0 0 16px;"><li>Сравнение тарифов и лимиты по ученикам</li><li>Каталог 200+ готовых программ ДПО и ПО</li><li>Презентация ИИ-конструктора курсов</li><li>Чек-лист по миграции существующих курсов</li></ul> <p style="font-size: 15px; color: #475569; line-height: 1.7; margin: 0 0 16px;">Готов ответить на любые вопросы и помочь с подбором тарифа. Когда удобно созвониться повторно?</p> <div style="text-align: center; margin: 28px 0 8px;"><a href="{{action_url}}" style="display: inline-block; background: #1AAB9B; color: white; padding: 14px 36px; border-radius: 12px; text-decoration: none; font-weight: 600; font-size: 15px; box-shadow: 0 4px 12px rgba(26,171,155,0.25);">Открыть материалы</a></div></div> <p style="font-size: 11px; color: #94A3B8; margin: 20px 0 0; text-align: center; line-height: 1.5;"> Платформа Sintagma — <a href="https://sintagma.com.ru" style="color: #94A3B8; text-decoration: underline;">sintagma.com.ru</a><br/> Если вы не хотите получать письма от Sintagma — ответьте на это письмо словом «СТОП». </p> </div></div>', subject='Материалы после встречи — Sintagma', category='followup', updated_at=now() WHERE scope='platform' AND name='Напоминание после КП';

UPDATE email_templates SET html_body='<div style="font-family: -apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, sans-serif; background: #F8FAFC; padding: 32px 16px;"><div style="max-width: 640px; margin: 0 auto;"><div style="background: white; border-radius: 16px; padding: 36px; box-shadow: 0 2px 12px rgba(15,23,42,0.06);"><h1 style="font-size: 22px; color: #0F172A; margin: 0 0 16px; font-weight: 700;">Коммерческое предложение</h1> <p style="font-size: 15px; color: #475569; line-height: 1.7; margin: 0 0 16px;">Для <strong style="color:#0F172A">{{name}}</strong> подготовили персональное предложение по платформе Sintagma.</p> <div style="background: #F8FAFC; border-left: 4px solid #1AAB9B; padding: 16px 20px; border-radius: 8px; margin: 16px 0;"><p style="font-size: 14px; color: #0F172A; margin: 0 0 8px; font-weight: 600;">Что входит в КП:</p><ul style="font-size: 14px; color: #475569; line-height: 1.7; padding-left: 18px; margin: 0;"><li>Подобранный тариф и стоимость на год</li><li>Список включённых программ обучения</li><li>Лимиты по ученикам, курсам и хранилищу</li><li>Условия миграции и поддержки</li></ul></div> <p style="font-size: 15px; color: #475569; line-height: 1.7; margin: 0 0 16px;">Предложение действует 14 дней. Готов обсудить детали и скорректировать условия под ваши задачи.</p> <div style="text-align: center; margin: 28px 0 8px;"><a href="{{action_url}}" style="display: inline-block; background: #1AAB9B; color: white; padding: 14px 36px; border-radius: 12px; text-decoration: none; font-weight: 600; font-size: 15px; box-shadow: 0 4px 12px rgba(26,171,155,0.25);">Открыть предложение</a></div></div> <p style="font-size: 11px; color: #94A3B8; margin: 20px 0 0; text-align: center; line-height: 1.5;"> Платформа Sintagma — <a href="https://sintagma.com.ru" style="color: #94A3B8; text-decoration: underline;">sintagma.com.ru</a><br/> Если вы не хотите получать письма от Sintagma — ответьте на это письмо словом «СТОП». </p> </div></div>', subject='Коммерческое предложение — Sintagma', category='proposal', updated_at=now() WHERE scope='platform' AND name='Отправка КП';

UPDATE email_templates SET html_body='<div style="font-family: -apple-system, BlinkMacSystemFont, ''Segoe UI'', Roboto, sans-serif; background: #F8FAFC; padding: 32px 16px;"><div style="max-width: 640px; margin: 0 auto;"><div style="background: white; border-radius: 16px; padding: 36px; box-shadow: 0 2px 12px rgba(15,23,42,0.06);"><h1 style="font-size: 22px; color: #0F172A; margin: 0 0 16px; font-weight: 700;">Давно не виделись, {{name}}!</h1> <p style="font-size: 15px; color: #475569; line-height: 1.7; margin: 0 0 16px;">Sintagma за это время сильно прокачалась. Самое интересное:</p> <ul style="font-size: 14px; color: #475569; line-height: 1.8; padding-left: 20px; margin: 0 0 16px;"><li><strong style="color:#0F172A">ИИ-аватар</strong> — голосовой преподаватель прямо в уроке</li><li><strong style="color:#0F172A">Документы 4.0</strong> — версионирование, корзина, KPI документооборота</li><li><strong style="color:#0F172A">Сделки 360°</strong> — тайм-лайн всех касаний с клиентом</li><li><strong style="color:#0F172A">Сотрудники с правами</strong> — гранулярная матрица + 2FA</li></ul> <p style="font-size: 15px; color: #475569; line-height: 1.7; margin: 0 0 8px;">Загляните — возможно, нужного раньше функционала уже ждёт вас в кабинете.</p> <div style="text-align: center; margin: 28px 0 8px;"><a href="{{action_url}}" style="display: inline-block; background: #1AAB9B; color: white; padding: 14px 36px; border-radius: 12px; text-decoration: none; font-weight: 600; font-size: 15px; box-shadow: 0 4px 12px rgba(26,171,155,0.25);">Что нового на платформе</a></div></div> <p style="font-size: 11px; color: #94A3B8; margin: 20px 0 0; text-align: center; line-height: 1.5;"> Платформа Sintagma — <a href="https://sintagma.com.ru" style="color: #94A3B8; text-decoration: underline;">sintagma.com.ru</a><br/> Если вы не хотите получать письма от Sintagma — ответьте на это письмо словом «СТОП». </p> </div></div>', subject='Что нового на Sintagma — возвращайтесь', category='cold', updated_at=now() WHERE scope='platform' AND name='Реактивация спящего клиента';